'use client'

import { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { WidgetRegistry } from './registry'

export interface InteractiveRendererProps {
  html: string
  className?: string
}

interface PortalTarget {
  id: string
  element: Element
  widgetType: string
  props: Record<string, any>
}

/**
 * Safe Multi-Portal Hydrator for Interactive Widgets.
 *
 * Renders static compiled HTML (with syntax highlighting and prose), finds all
 * `[data-widget]` placeholder nodes generated by the content build, and mounts
 * matching React widgets via `createPortal`.
 *
 * Guarantees zero `eval()`, zero runtime MDX evaluation, and full offline
 * compatibility inside Tauri desktop app.
 */
export function InteractiveRenderer({ html, className }: InteractiveRendererProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [portals, setPortals] = useState<PortalTarget[]>([])

  useEffect(() => {
    if (!containerRef.current) return

    const mounts = containerRef.current.querySelectorAll('[data-widget]')
    const targets: PortalTarget[] = []

    mounts.forEach((el, index) => {
      const widgetType = el.getAttribute('data-widget')
      const rawProps = el.getAttribute('data-widget-props')
      if (!widgetType || !rawProps) return

      try {
        const props = JSON.parse(rawProps)
        targets.push({
          id: `widget-${widgetType}-${index}`,
          element: el,
          widgetType,
          props,
        })
      } catch (err) {
        console.error(`Failed to parse props for widget "${widgetType}":`, err)
      }
    })

    setPortals(targets)
  }, [html])

  return (
    <>
      <div
        ref={containerRef}
        className={className}
        dangerouslySetInnerHTML={{ __html: html }}
      />
      {portals.map(({ id, element, widgetType, props }) => {
        const WidgetComponent = WidgetRegistry[widgetType]
        if (!WidgetComponent) {
          return null
        }
        return createPortal(<WidgetComponent key={id} {...props} />, element)
      })}
    </>
  )
}
